                String line;
                while ((line = br.readLine()) != null) {
                    errorBuilder.append(line).append("\n");
                    logger.debug("Exec [{}]: '{}'", "ERROR", line);
                }
            } catch (IOException e) {
                logger.warn("An exception occurred while reading the stderr when executing '{}' : '{}'", commandLine,
