            proxy_host,
            proxy_port,
            proxy_rdns,
            proxy_user,
            proxy_pass,
            proxy_headers,
        ) = self.proxy_info.astuple()

        host = proxy_host
        port = proxy_port
    else:
        use_proxy = False

