    statecasedefault(context->policy.state);
    }
cleanup:
    ifapi_free_node_list(context->policy.eval_ctx.policy_elements);
    context->policy.eval_ctx.policy_elements = NULL;
    context->policy.state = POLICY_INIT;
    return r;
}
