                        // target time unit.
                        // Doing an inverse math since convert will return 0 when converting
                        // smaller units (i.e. 1 second) to bigger units (i.e. days)
                        multiplyingFactor = 1d / TimeUnit.SECONDS.convert(1, timeUnit);
